const b = EntityActionContext.entityObject;
return [
  `Batch ${b.JournalEntryBatchNumber} for ${b.Company} is now ${b.Status}.`,
  `Target system: ${b.TargetSystem}`,
  `Posting date: ${b.PostingDate}`,
  `Entries: ${b.TotalEntries}   Debits: ${b.TotalDebits}   Credits: ${b.TotalCredits}`,
  `External reference: ${b.ExternalJournalEntryBatchRef ?? '(none)'}`,
  b.ErrorMessage ? `Error reported by the target system: ${b.ErrorMessage}` : ''
].filter(Boolean).join('\n');

const je = EntityActionContext.entityObject;
return [
  `Journal entry ${je.EntryNumber} was created for ${je.Company}.`,
  `Type: ${je.EntryType}`,
  `Effective date: ${je.EffectiveDate}`,
  `Status: ${je.Status}`,
  `Description: ${je.Description ?? '(none)'}`
].join('\n');
